"""Render the measured per-Die distribution and paired transport comparison."""
import json,sys,statistics,shutil,html
from pathlib import Path
from run import csvread,dump,sha,HERE,BINARY
root=Path(sys.argv[1]).resolve();rr=json.loads((root/'results.json').read_text());groups={}
for r in rr:
 key=(r['model'],r['chips'],r['tp'],r['batch'])
 groups.setdefault(key,{}).setdefault(r['moe_transport'],[]).append(r)
table=''
for key,policies in groups.items():
 vals={p:statistics.mean(x['per_step_block_us'] for x in rows) for p,rows in policies.items()}
 table+='<tr>'+''.join(f'<td>{html.escape(str(v))}</td>' for v in key)+f'<td>{format(vals["leader"],".3f") if "leader" in vals else "—"}</td><td>{vals["tp-striped"]:.3f}</td><td>{len(policies["tp-striped"])}</td></tr>'
data=[]
for r in rr:
 if r['model']=='glm-5.3' and r['tp']==4 and r['batch']==8 and r['seed']==1:
  data.append(dict(policy=r['moe_transport'],rows=csvread(Path(r['run'])/'moe_die_traffic.csv'),url=str(Path(r['run']).relative_to(root))+'/moe_die_traffic.csv'))
text='''<!doctype html><html lang="zh"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SUE v2 · 多Die MoE收发验收</title><style>body{font:16px/1.7 system-ui,sans-serif;background:#f3f7fb;color:#183049;max-width:1100px;margin:auto;padding:24px}h1{font-size:32px}section{background:white;border:1px solid #dbe6ee;border-radius:12px;padding:24px;margin:20px 0}table{border-collapse:collapse;width:100%}td,th{padding:10px;border-bottom:1px solid #dbe6ee;text-align:left}a{color:#247ba0}.scroll{overflow:auto}.note{border-left:4px solid #d98232;padding:15px;background:#fff5e3}select{padding:10px}svg{width:100%;min-width:650px}svg text{font:13px system-ui;fill:#183049}</style><h1>SUE v2：MoE改为所有活跃TP Die协同收发</h1><p>25项逐包验收通过 · 三模型 · 同种子专家选择不变 · 底层SUE协议未改</p><p class="note">这次验证的是通信布局修正。表中是代表块时延，不是完整TPOT；先前327项报告尚未全量重跑，旧性能结论不能直接套用新布局。</p><section><h2>实际流量：8个发送Die → 32个</h2><p>GLM 5.3 / 8芯片 / TP4 / batch8 / 8K / seed1。每格显示两步窗口累计应用载荷KB，包含分片元数据，不含协议头和ACK。零值也显示。颜色以当前两张图共同最大值归一化。</p><label>方向 <select id="metric"><option value="fabric_tx_bytes">发送到fabric</option><option value="fabric_rx_bytes">从fabric接收</option></select></label> <label>阶段 <select id="phase"><option value="dispatch">专家分发 dispatch</option><option value="combine">专家返回 combine</option></select></label><div class="scroll" id="heat"></div><p>专家只在owner Die计算并返回。未被选中的专家无需发送，故返回端不保证每个Die都有流量。活跃TP组的分发端和返回接收端均可使用所有Die。</p></section><section><h2>完整布局对照（µs / 代表块）</h2><p>两步窗口除以2，表中为种子均值。batch1单独验证，仅一个种子；旧方案未测用—标记。默认新布局也改用了分片归并＋AllGather，因此差异不只来自出口分散。</p><div class="scroll"><table><tr><th>模型</th><th>芯片</th><th>TP</th><th>batch</th><th>集中收发</th><th>多Die分片</th><th>种子数</th></tr>@@TABLE@@</table></div></section><section><h2>数据如何流动</h2><ol><li>公共计算后的TP AllReduce使激活在组内复制。</li><li>每个Die读取激活的不同特征切片，发往同一个专家；每片独立附8B元数据。</li><li>专家收到全部切片后，只执行一次对应计算。</li><li>结果按特征切片返回所有Die，各Die归并top-k专家贡献，并计计算与HBM服务。</li><li>TP AllGather恢复复制布局。芯片内走有竞争的D2D环，跨芯片走各Die独立SUE端口。</li></ol><p>参与发送不等于链路满载。小流、端口哈希、专家落点和计算等待仍影响利用率；未激活的DP组不凭空发包。</p><p><a href="verification.json">验收记录</a> · <a href="results.json">全部结果</a> · <a href="design.json">实验条件</a> · <a href="RESOURCE_MODEL.md">建模说明</a></p></section><script>const D=@@DATA@@;function draw(){let m=document.getElementById('metric').value,p=document.getElementById('phase').value,max=Math.max(1,...D.flatMap(d=>d.rows.filter(r=>r.phase===p).map(r=>+r[m])));document.getElementById('heat').innerHTML=D.map(d=>{let rows=d.rows.filter(r=>r.phase===p),s='<svg viewBox="0 0 850 360"><text x="20" y="25">'+(d.policy==='leader'?'旧：集中收发':'新：多Die分片')+'</text>';for(let c=0;c<8;c++){s+='<text x="'+(120+c*90)+'" y="58">芯片'+c+'</text>';for(let die=0;die<4;die++){let r=rows.find(x=>+x.chip===c&&+x.die===die),v=+r[m];s+='<rect x="'+(110+c*90)+'" y="'+(75+die*60)+'" width="83" height="48" rx="5" fill="rgba(36,123,160,'+(.06+.6*v/max)+')"/><text x="'+(120+c*90)+'" y="'+(104+die*60)+'">'+(v/1000).toFixed(1)+'</text>';}}for(let die=0;die<4;die++)s+='<text x="20" y="'+(104+die*60)+'">Die '+die+'</text>';return s+'</svg><a href="'+d.url+'">逐Die原始CSV</a>';}).join('');}document.getElementById('metric').onchange=draw;document.getElementById('phase').onchange=draw;draw();</script></html>'''.replace('@@TABLE@@',table).replace('@@DATA@@',json.dumps(data))
(root/'report.html').write_text(text)
shutil.copy2(HERE/'RESOURCE_MODEL.md',root/'RESOURCE_MODEL.md')
src=root/'source';src.mkdir(exist_ok=True)
for name in ['inference_experiments.py','moe_traffic.py','verify_moe_striping.py','report_moe_striping.py']:shutil.copy2(HERE/name,src/name)
dump(root/'implementation.json',{'binary_sha256':sha(BINARY),'sources':{p.name:sha(p) for p in src.glob('*.py')}})
